            with open(path, 'r', encoding='utf-8', errors='replace') as fh:
                for tok in tokenize.generate_tokens(fh.readline):
                    if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                        results.append((path, tok.start[0]))
        except Exception:
            pass

results.sort()
with open('todos.txt', 'w', encoding='utf-8') as out:
    for path, line in results:
        out.write('%s:%d\n' % (path, line))
